document.addEventListener("DOMContentLoaded",function(){function getCSRFToken(){return document.cookie.split("; ").find((row)=>row.startsWith("csrftoken="))?.split("=")[1];}
document.getElementById("contact-form").addEventListener("submit",function(event){event.preventDefault();let formData={name:document.getElementById("cf-name").value,phone:document.getElementById("cf-phone").value,email:document.getElementById("cf-email").value,message:document.getElementById("cf-message").value,};fetch("/contact/submit/",{method:"POST",headers:{"Content-Type":"application/json","X-CSRFToken":getCSRFToken(),},body:JSON.stringify(formData),}).then((response)=>response.json()).then((data)=>{if(data.status==="success"){alert("Your message has been sent successfully!");document.getElementById("contact-form").reset();}else{alert("Error: "+data.message);}}).catch(()=>{alert("An error occurred. Please try again.");});});});;{"@context":"http://schema.org","@type":"Person","name":"Vincent Kiplangat","url":"http://yourwebsite.com","jobTitle":"Developer, Data Scientist, Network and Cloud, engineer","sameAs":["http://www.linkedin.com/in/vincent-kiplangat-9510621bb/","https://github.com/VincentKiplangat"]};$(document).ready(function(){$("#contact-form").attr("action","/contact/submit/");});;